import type { ComboboxDividerProps } from "../combobox.types";

import { forwardRef } from "react";
import { clsx } from "clsx";

import { ComboboxClasses } from "../combobox.styles";

const ComboboxDivider = forwardRef<HTMLDivElement, ComboboxDividerProps>(
  ({ className, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={clsx(ComboboxClasses.divider, className)}
        role="separator"
        {...props}
      />
    );
  },
);

ComboboxDivider.displayName = "Combobox.Divider";

export { ComboboxDivider };
